'use strict';

function splitEpochNanos(value) {
  let nanos;
  if (typeof value === 'bigint') {
    nanos = value;
  } else if (typeof value === 'string' && /^\d+$/.test(value)) {
    nanos = BigInt(value);
  } else {
    throw new TypeError('value must be a non-negative bigint or decimal string');
  }

  if (nanos < 0n) {
    throw new RangeError('value must be non-negative');
  }

  const milliseconds = nanos / 1000000n;
  if (milliseconds > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new RangeError('millisecond component is too large');
  }

  return {
    epochMilliseconds: Number(milliseconds),
    remainderNanoseconds: Number(nanos % 1000n)
  };
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validateMeasurement(value) {
  if (!isRecord(value) ||
      typeof value.device !== 'string' || value.device.length === 0 ||
      typeof value.metric !== 'string' || value.metric.length === 0 ||
      typeof value.value !== 'number' || !Number.isFinite(value.value)) {
    throw new TypeError('invalid measurement');
  }

  try {
    return splitEpochNanos(value.atNanos);
  } catch {
    throw new TypeError('invalid measurement');
  }
}

class FeedMapper {
  constructor(useModernProtocol) {
    this.useModernProtocol = Boolean(useModernProtocol);
  }

  canHandle(packet) {
    try {
      if (!isRecord(packet)) return false;

      const singular = this.useModernProtocol ? 'sample' : 'reading';
      const plural = this.useModernProtocol ? 'samples' : 'readings';
      if (packet.kind !== singular && packet.kind !== plural) return false;

      const measurements = packet.kind === plural ? packet.data : [packet.data];
      if (!Array.isArray(measurements)) return false;

      for (const measurement of measurements) {
        validateMeasurement(measurement);
      }
      return true;
    } catch {
      return false;
    }
  }

  getTopics(devices) {
    if (!Array.isArray(devices)) {
      throw new TypeError('devices must be an array');
    }

    const seen = new Set();
    const result = [];
    const prefix = this.useModernProtocol ? 'modern/' : 'legacy/';
    for (const device of devices) {
      if (typeof device !== 'string' || device.length === 0) {
        throw new TypeError('device names must be non-empty strings');
      }
      if (!seen.has(device)) {
        seen.add(device);
        result.push(prefix + device);
      }
    }
    return result;
  }

  *map(packet, receivedSequence) {
    if (!Number.isSafeInteger(receivedSequence) || receivedSequence < 0) {
      throw new TypeError('receivedSequence must be a non-negative safe integer');
    }
    if (!isRecord(packet)) {
      throw new TypeError('invalid packet');
    }

    const singular = this.useModernProtocol ? 'sample' : 'reading';
    const plural = this.useModernProtocol ? 'samples' : 'readings';
    if (packet.kind !== singular && packet.kind !== plural) {
      throw new TypeError('unsupported packet');
    }

    const measurements = packet.kind === plural ? packet.data : [packet.data];
    if (!Array.isArray(measurements)) {
      throw new TypeError('plural packet data must be an array');
    }

    const results = measurements.map(measurement => ({
      device: measurement && measurement.device,
      metric: measurement && measurement.metric,
      value: measurement && measurement.value,
      timestamp: validateMeasurement(measurement),
      receivedSequence
    }));

    yield* results;
  }
}

module.exports = { splitEpochNanos, FeedMapper };

