'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['FeedMapper', 'splitEpochNanos']);
const { splitEpochNanos, FeedMapper } = api;

assert.deepStrictEqual(splitEpochNanos(0n), { epochMilliseconds: 0, remainderNanoseconds: 0 });
assert.deepStrictEqual(splitEpochNanos('1000001'), { epochMilliseconds: 1, remainderNanoseconds: 1 });
assert.deepStrictEqual(splitEpochNanos('0002000003'), { epochMilliseconds: 2, remainderNanoseconds: 3 });
const maxNanos = BigInt(Number.MAX_SAFE_INTEGER) * 1000000n + 999999n;
assert.deepStrictEqual(splitEpochNanos(maxNanos), {
  epochMilliseconds: Number.MAX_SAFE_INTEGER,
  remainderNanoseconds: 999999
});
for (const bad of [-1n, '-1', '', ' ', '1.0', '+1', 1, null, {}, []]) {
  assert.throws(() => splitEpochNanos(bad), error => error instanceof TypeError || error instanceof RangeError);
}
assert.throws(
  () => splitEpochNanos((BigInt(Number.MAX_SAFE_INTEGER) + 1n) * 1000000n),
  RangeError
);

const legacy = new FeedMapper(false);
const modern = new FeedMapper(true);
const legacyMeasurement = Object.freeze({ device: 'd1', metric: 'temp', value: 12.5, atNanos: '2500007' });
const legacyPacket = Object.freeze({ kind: 'reading', data: legacyMeasurement });
assert.strictEqual(legacy.canHandle(legacyPacket), true);
assert.strictEqual(legacy.canHandle({ kind: 'readings', data: [] }), true);
assert.strictEqual(legacy.canHandle({ kind: 'sample', data: legacyMeasurement }), false);
assert.strictEqual(modern.canHandle({ kind: 'sample', data: legacyMeasurement }), true);
assert.strictEqual(modern.canHandle({ kind: 'samples', data: [] }), true);
assert.strictEqual(modern.canHandle({ kind: 'reading', data: legacyMeasurement }), false);
for (const malformed of [null, undefined, 4, [], {}, { kind: 'reading' }, { kind: 'readings', data: null }]) {
  assert.doesNotThrow(() => legacy.canHandle(malformed));
  assert.strictEqual(legacy.canHandle(malformed), false);
}

assert.deepStrictEqual(legacy.getTopics(['a', 'b', 'a', 'c']), ['legacy/a', 'legacy/b', 'legacy/c']);
assert.deepStrictEqual(modern.getTopics([]), []);
assert.deepStrictEqual(modern.getTopics(['x']), ['modern/x']);
for (const bad of [null, {}, 'x', ['', 'x'], ['x', 3]]) {
  assert.throws(() => legacy.getTopics(bad), TypeError);
}
const devices = Object.freeze(['a', 'a', 'b']);
assert.deepStrictEqual(legacy.getTopics(devices), ['legacy/a', 'legacy/b']);

assert.deepStrictEqual([...legacy.map(legacyPacket, 0)], [{
  device: 'd1', metric: 'temp', value: 12.5,
  timestamp: { epochMilliseconds: 2, remainderNanoseconds: 500007 },
  receivedSequence: 0
}]);
const measurements = Object.freeze([
  Object.freeze({ device: 'd2', metric: 'm1', value: 0, atNanos: 0n }),
  Object.freeze({ device: 'd3', metric: 'm2', value: -3.25, atNanos: '999999' })
]);
const packet = Object.freeze({ kind: 'samples', data: measurements });
const mapped = [...modern.map(packet, Number.MAX_SAFE_INTEGER)];
assert.deepStrictEqual(mapped, [
  { device: 'd2', metric: 'm1', value: 0, timestamp: { epochMilliseconds: 0, remainderNanoseconds: 0 }, receivedSequence: Number.MAX_SAFE_INTEGER },
  { device: 'd3', metric: 'm2', value: -3.25, timestamp: { epochMilliseconds: 0, remainderNanoseconds: 999999 }, receivedSequence: Number.MAX_SAFE_INTEGER }
]);
assert.notStrictEqual(mapped[0], measurements[0]);
assert.notStrictEqual(mapped[1], measurements[1]);
assert.notStrictEqual(mapped[0].timestamp, mapped[1].timestamp);
assert.deepStrictEqual([...modern.map({ kind: 'samples', data: [] }, 1)], []);

for (const sequence of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '1']) {
  assert.throws(() => [...modern.map({ kind: 'samples', data: [] }, sequence)], TypeError);
}
const badMeasurements = [
  { device: '', metric: 'm', value: 1, atNanos: 0n },
  { device: 'd', metric: '', value: 1, atNanos: 0n },
  { device: 'd', metric: 'm', value: Infinity, atNanos: 0n },
  { device: 'd', metric: 'm', value: 1, atNanos: -1n }
];
for (const measurement of badMeasurements) {
  assert.throws(() => [...modern.map({ kind: 'sample', data: measurement }, 1)], TypeError);
}
for (const badPacket of [null, [], {}, { kind: 'reading', data: legacyMeasurement }, { kind: 'sample', data: [] }, { kind: 'samples', data: {} }]) {
  assert.throws(() => [...modern.map(badPacket, 1)], TypeError);
}
assert.throws(() => [...modern.map({ kind: 'samples', data: [measurements[0], badMeasurements[0]] }, 1)], TypeError);

